public sealed class CheckoutCoordinator(
    IPricingService pricing,
    IPromotionService promotions,
    ITenderResolver tenders,
    IFulfilmentScheduler fulfilment,
    IAuditStore audit)
{
    public CheckoutResult Complete(
        CheckoutSession session,
        Order order,
        Customer customer)
    {
        if (!session.HasBegun)
            return CheckoutResult.Failure(CheckoutError.NotStarted);

        var total = pricing.CalculateTotal(order, customer);
        var tender = tenders.Resolve(order, customer, total);
        var tasks = fulfilment.Schedule(order);
